    <div class="scrollbar"><span></span></div>
  </main>
<script>
  const editor = document.getElementById('editor');
  document.getElementById('moreButton').addEventListener('click', () => {
    document.getElementById('statsSummary').classList.add('hidden');
    document.getElementById('expandedStats').classList.add('visible');
  });
  document.getElementById('fewerButton').addEventListener('click', () => {
    document.getElementById('expandedStats').classList.remove('visible');
    document.getElementById('statsSummary').classList.remove('hidden');
  });
  document.querySelectorAll('.eye').forEach(button => {
    button.addEventListener('click', () => {
      const type = button.dataset.type;
      document.querySelectorAll('.' + type).forEach(mark => {
        mark.style.backgroundColor = mark.style.backgroundColor ? '' : 'transparent';
      });
      button.style.opacity = button.style.opacity === '0.45' ? '1' : '0.45';
    });
  });
  document.querySelectorAll('.editor mark').forEach(mark => {
    mark.addEventListener('click', () => {
      mark.style.backgroundColor = 'transparent';
    });
  });
  document.getElementById('writeButton').addEventListener('click', () => {
    editor.classList.add('hide-highlights');
    editor.setAttribute('contenteditable', 'true');
    document.getElementById('writeButton').classList.add('active');
    document.getElementById('editButton').classList.remove('active');
  });
  document.getElementById('editButton').addEventListener('click', () => {
    editor.classList.remove('hide-highlights');
    editor.setAttribute('contenteditable', 'false');
    document.getElementById('editButton').classList.add('active');
    document.getElementById('writeButton').classList.remove('active');
  });
  document.getElementById('menuButton').addEventListener('click', () => {
    document.getElementById('menuPop').classList.toggle('open');
  });
  document.getElementById('settingsButton').addEventListener('click', () => {
    document.getElementById('settingsPop').classList.toggle('open');
  });
  document.getElementById('feedbackButton').addEventListener('click', () => {
    alert('Thanks for your feedback!');
  });
</script>
</body>
</html>
